/*
 * A233865  Numbers n such that sigma(sigma(n))+1 is prime.
 * https://oeis.org/A233865
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 n <= 18, u16 n <= 1524, u32 n <= 2431, u64 n <= 5800,
 *            u128 n <= 5800, big any n
 * Helpers:   is_prime_big, sigma_of
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Computes the nth term of A233865:
   numbers n such that sigma(sigma(n)) + 1 is prime.  */
/* The sequence is generated by searching integers in
   increasing order and storing those that satisfy the condition.  */

#include <stddef.h>
#include <stdint.h>
#include <stdlib.h>
#include <stdbool.h>

/* Helper functions from the utils package.  */
#include "../utils/sigma_of.h"      /* seq_t sigma_of(idx_t n); */
#include "../utils/is_prime_big.h"  /* bool is_prime_big(seq_t n); */

seq_t a(idx_t n)
{
    static seq_t *terms = NULL;        /* cached list of terms */
    static size_t terms_cap = 0;       /* allocated capacity */
    static size_t terms_len = 0;       /* number of terms stored */
    static idx_t last_checked = 0;    /* last integer examined */

    if (n == 0)                       /* offset is 1; 0 is undefined */
        return 0;

    /* Initialise storage on first call.  */
    if (terms_cap == 0) {
        terms_cap = 16;
        terms = (seq_t *)malloc(terms_cap * sizeof(seq_t));
    }

    /* Generate terms until we have at least n terms stored.  */
    while (terms_len < (size_t)n) {
        last_checked++;

        /* Compute sigma(n) and sigma(sigma(n)).  */
        seq_t s1 = sigma_of((idx_t)last_checked);
        /* If s1 is larger than the largest representable idx_t,
           we cannot continue – skip this value.  */
        if (s1 > (seq_t)UINT64_MAX)
            continue;

        seq_t s2 = sigma_of((idx_t)s1);

        /* Test whether sigma(sigma(n)) + 1 is prime.  */
        seq_t p = s2 + (seq_t)1;
        if (is_prime_big(p)) {
            /* Ensure enough space in the array.  */
            if (terms_len == terms_cap) {
                terms_cap <<= 1;
                terms = (seq_t *)realloc(terms, terms_cap * sizeof(seq_t));
            }
            terms[terms_len++] = (seq_t)last_checked;
        }
    }

    return terms[n - 1];   /* zero‑based index into the stored terms */
}
